  1	/**
  2	 * GUI API Route Handlers
  3	 *
  4	 * Pure async functions — one per REST endpoint. Each handler accepts parsed
  5	 * request parameters and returns a result object (or throws a structured error).
  6	 * The HTTP server (gui/server.ts) calls these handlers and maps results to HTTP
  7	 * responses.
  8	 *
  9	 * Error shape:  { code: string, message: string, details?: unknown }
 10	 *   NOT_FOUND        → 404
 11	 *   FORBIDDEN        → 403
 12	 *   VALIDATION_ERROR → 400
 13	 *   (unhandled)      → 500
 14	 *
 15	 * STDIO discipline: this file never writes to process.stdout.
 16	 */
 17	
 18	import { rm, readFile, readdir } from 'node:fs/promises';
 19	import { join, resolve, sep } from 'node:path';
 20	import { z } from 'zod';
 21	import { LedgerStore, SlugConflictError } from '../src/storage/ledger-store.js';
 22	import { withLock } from '../src/storage/file-lock.js';
 23	import { inferProjectRootFromPlanPath, resolveProjectDir } from '../src/utils/ledger-root.js';
 24	import { assertSafeSegment } from '../src/utils/path-validator.js';
 25	import { readProjectName } from '../src/utils/read-project-name.js';
 26	import { PLAN_ARCHIVE_FILENAME, SYNTHESIS_ARCHIVE_FILENAME, DIALOGUES_DIR, CHUNKS_DIR } from '../src/utils/constants.js';
 27	import {
 28	  PIPELINE_AGENT_MAP,
 29	  DEFAULT_PIPELINE_STAGES,
 30	  CANONICAL_PIPELINE_ORDERING,
 31	} from '../src/utils/pipeline-maps.js';
 32	import type { PipelineType } from '../src/utils/pipeline-maps.js';
 33	import { ProjectMetaSchema } from '../src/schema/project-meta.js';
 34	import type { ProjectMeta } from '../src/schema/project-meta.js';
 35	import type { ProjectStatus, WorkPackageStatus } from '../src/schema/enums.js';
 36	import type { RootIndex } from '../src/schema/root-index.js';
 37	import type { IncidentContext, WorkPackageDetail } from '../src/schema/work-package.js';
 38	
 39	/**
 40	 * Extended WP detail response that includes the server's canonical default pipeline stages.
 41	 * The extra field is additive — all existing fields of WorkPackageDetail are preserved.
 42	 */
 43	export type WorkPackageDetailResponse = WorkPackageDetail & {
 44	  default_pipeline_stages: string[];
 45	};
 46	import { getConfig, writeConfig, GuiConfigPartialSchema } from '../src/gui/config.js';
 47	import type { GuiConfig } from '../src/gui/config.js';
 48	import {
 49	  analyzeProjectForReset,
 50	  applyProjectReset,
 51	  getPassedStages,
 52	  markProjectComplete,
 53	} from '../src/utils/project-reset.js';
 54	import type {
 55	  WpDecision,
 56	  ProjectResetDiagnosis,
 57	  ProjectResetResult,
 58	  MarkProjectCompleteResult,
 59	} from '../src/utils/project-reset.js';
 60	import { ApiError } from '../src/gui/errors.js';
 61	export { ApiError };
 62	import {
 63	  getQueue,
 64	  killQueueEntry,
 65	  dismissQueueEntry,
 66	  startOrchestrator,
 67	  getRunStatus,
 68	} from './orchestrator-manager.js';
 69	import type { QueueEntry, KillResult, StartResult, RunStatus } from './orchestrator-manager.js';
 70	
 71	
 72	// ---------------------------------------------------------------------------
 73	// Internal helpers
 74	// ---------------------------------------------------------------------------
 75	
 76	function notFound(message: string): never {
 77	  throw new ApiError('NOT_FOUND', message);
 78	}
 79	
 80	function forbidden(message: string): never {
 81	  throw new ApiError('FORBIDDEN', message);
 82	}
 83	
 84	function conflict(message: string): never {
 85	  throw new ApiError('CONFLICT', message);
 86	}
 87	
 88	function validationError(message: string, details?: unknown): never {
 89	  throw new ApiError('VALIDATION_ERROR', message, details);
 90	}
 91	
 92	/**
 93	 * Allowlist for WP IDs and queue entry IDs: must start with alnum, then word chars or hyphens.
 94	 * Note: `\w` includes underscore intentionally — WP IDs (`WP-001`) and queue entry IDs may
 95	 * contain underscores in future formats. This is permissive by design.
 96	 */
 97	const SAFE_ID_PATTERN = /^[A-Za-z0-9][\w-]*$/;
 98	
 99	/**
100	 * Guards against path-traversal attacks on the project slug URL parameter.

101	 * @throws ApiError VALIDATION_ERROR for any rejected value.
102	 */
103	export function parseKnowledgeId(raw: string): number {
104	  // Reject strings containing a decimal point before numeric coercion —
105	  // this catches "1.5" and also "2.0", both of which the caller must treat
106	  // as non-integer IDs even though Number("2.0") === 2.
107	  if (raw.includes('.')) {
108	    throw new ApiError('VALIDATION_ERROR', 'Invalid insight id.');
109	  }
110	  const n = Number(raw);
111	  if (!Number.isInteger(n) || n <= 0) {
112	    throw new ApiError('VALIDATION_ERROR', 'Invalid insight id.');
113	  }
114	  return n;
115	}
116	
117	// ---------------------------------------------------------------------------
118	// Interface definitions
119	// ---------------------------------------------------------------------------
120	
121	/** Raw query parameters accepted by GET /api/knowledge. */
122	export interface KnowledgeListParams {
123	  scope?: string;
124	  category?: string;
125	  /** Comma-separated list of tags to filter by. */
126	  tags?: string;
127	  project_slug?: string;
128	  /** Full-text search query — delegates to searchInsights when present. */
129	  query?: string;
130	  limit?: number | string;
131	  offset?: number | string;
132	}
133	
134	// ---------------------------------------------------------------------------
135	// GET /api/knowledge
136	// ---------------------------------------------------------------------------
137	
138	/**
139	 * Lists (or searches) knowledge insights stored in the ledger's `.knowledge/` directory.
140	 *
141	 * - When `query` is present, delegates to `KnowledgeStoreManager.searchInsights()`.
142	 * - Otherwise calls `KnowledgeStoreManager.listInsights()` with scope/category/tags filters.
143	 * - `scope` is validated via `InsightScope.safeParse()`; unrecognised values are silently
144	 *   treated as "no scope filter" rather than causing an error.
145	 * - `tags` is a comma-separated string that is split before being forwarded.
146	 * - `limit` and `offset` are coerced to non-negative integers; invalid/missing values
147	 *   are silently ignored (limit → undefined, offset → 0).
148	 *
149	 * @note When `query` is present, `limit`, `offset`, and `tags` are **not forwarded** to
150	 *   `searchInsights()` — that method does not support pagination or tag filtering.
151	 *   Callers that need to combine full-text search with tag filtering should post-process
152	 *   the returned array. This constraint was not addressed in WP-004 or WP-005 and remains
153	 *   open for a future work package.
154	 */
155	export async function handleListKnowledge(
156	  ledgerRoot: string,
157	  params: KnowledgeListParams = {}
158	): Promise<Insight[]> {
159	  const manager = new KnowledgeStoreManager(ledgerRoot);
160	
161	  // Validate scope — unrecognised values fall back to undefined (no filter).
162	  const scopeResult = InsightScope.safeParse(params.scope);
163	  const scope = scopeResult.success ? scopeResult.data : undefined;
164	
165	  const category = params.category ?? undefined;
166	  const project_slug = params.project_slug ?? undefined;
167	
168	  // Split comma-separated tags; ignore empty segments.
169	  const tags =
170	    params.tags && params.tags.trim().length > 0
171	      ? params.tags
172	          .split(',')
173	          .map((t) => t.trim())
174	          .filter((t) => t.length > 0)
175	      : undefined;
176	
177	  // Coerce pagination params.
178	  const limitRaw = params.limit !== undefined ? Math.floor(Number(params.limit)) : NaN;
179	  const limit = !isNaN(limitRaw) && limitRaw > 0 ? limitRaw : undefined;
180	
181	  const offsetRaw = params.offset !== undefined ? Math.floor(Number(params.offset)) : NaN;
182	  const offset = !isNaN(offsetRaw) && offsetRaw >= 0 ? offsetRaw : 0;
183	
184	  if (params.query && params.query.trim().length > 0) {
185	    return manager.searchInsights(params.query.trim(), { scope, project_slug, category });
186	  }
187	
188	  return manager.listInsights({ scope, category, tags, project_slug, limit, offset });
189	}
190	
191	// ---------------------------------------------------------------------------
192	// PATCH /api/knowledge/:id
193	// ---------------------------------------------------------------------------
194	
195	/**
196	 * Updates an existing knowledge insight identified by its numeric ID.
197	 *
198	 * Validates the raw ID string via `parseKnowledgeId` (throws VALIDATION_ERROR
199	 * for non-integer, zero, or floating-point strings). Validates the request body
200	 * via `KnowledgeUpdateBodySchema` (throws VALIDATION_ERROR for unknown fields or
201	 * type mismatches). Extracts `scope` and `project_slug` discriminator fields to
202	 * scope the update to the correct store.
203	 *
204	 * `superseded_by: null` in the body is mapped to `undefined` so the field is
205	 * cleared (removed) on the stored insight.
206	 *
207	 * Throws NOT_FOUND when no insight with the given ID exists in the specified scope.
208	 *
209	 * @param ledgerRoot  Absolute path to the central ledger root.
